                if predicate(&entry) {
                    entries.push(entry);
                }
            }
        }

        Ok(entries)
    }

    /// Rewrite all entries (for updates).
    fn rewrite_all(&self, entries: &[FeedbackEntry]) -> Result<()> {
        self.ensure_dir()?;

        let mut file = File::create(&self.path)?;
        for entry in entries {
            let json = serde_json::to_string(entry)?;
            writeln!(file, "{}", json)?;
        }

        Ok(())
    }
}

