    let etag = response
        .headers()
        .get("etag")
        .and_then(|v| v.to_str().ok())
        .map(String::from);

    let last_modified = response
        .headers()
        .get("last-modified")
        .and_then(|v| v.to_str().ok())
        .map(String::from);

    let content = response.text()?;

    if content.len() as u64 > self.max_response_size {
        return Err(BivvyError::FetchError {
            url: url.to_string(),
            message: format!(
                "Response too large ({} bytes, max {} bytes)",
                content.len(),
                self.max_response_size
            ),
        });
    }

    Ok(FetchResponse {
        content,
        etag,
        last_modified,
    })
}

