        if name.contains(&target) {
            if let Some(url) = asset["browser_download_url"].as_str() {
                return Ok(url.to_string());
            }
        }
    }

    anyhow::bail!(
        "No release asset found for platform '{}' in v{}",
        target,
        info.latest
    )
}

/// Return the Rust target triple fragment for this platform.
