        // depth2 extends depth3
        let depth2_yaml = format!(
            "extends:\n  - url: {}\napp_name: depth2\n",
            server.url("/depth3.yml")
        );
        // depth1 extends depth2
        let depth1_yaml = format!(
            "extends:\n  - url: {}\napp_name: depth1\n",
